// The guide's pages (generated by tools/learn.ts): translate the page, then start each live example.
import {embed} from "./embed";
import {loadLocale} from "./i18n";

await loadLocale();

// shortcut: an example keeps running after it scrolls out of view; pause off-screen ones if a chapter gets heavy
for (const figure of document.querySelectorAll<HTMLElement>(".example")) {
    const errors = figure.querySelector<HTMLElement>(".errors")!;
    embed(figure.querySelector("iframe")!, "../runner.html", figure.dataset.code!, message => errors.textContent += `${message}\n`);
}
